DATA.enunciados.push(...([{"fonte": "TJSC – Grupo de Câmaras de Direito Civil", "n": "I", "ord": 1, "texto": "Nas ações de cobrança de indenização a título de seguro obrigatório DPVAT, ou nos pleitos de complementação da quantia paga administrativamente, a condenação da seguradora acionada ao pagamento de valor a menor do que o postulado, na dicção do Enunciado n. 474 da Súmula do Superior Tribunal de Justiça, não importa julgamento citra petita, mesmo nos casos em que a parte autora fundamenta o pedido na inaplicabilidade das tabelas utilizadas para o cálculo do quantum.", "materia": "", "orgao": "Grupo de Câmaras de Direito Civil", "situacao": "Vigente", "obs": "\"Os integrantes do Grupo de Câmaras de Direito Civil, reunidos em sessão ordinária ocorrida em 10-4-2013, aprovaram o seguinte Enunciado, pertinente a matéria de seguro obrigatório DPVAT: · REDAÇÃO ORIGINAL, PUBLICADA NO DJE N. 1668, DISPONIBILIZADO EM 9-7-2013", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Civil", "n": "II", "ord": 2, "texto": "Para o cálculo da renda mensal inicial de benefício de previdência privada aplicam-se as regras regulamentares vigentes no momento do preenchimento dos requisitos para a concessão do benefício pleiteado.", "materia": "", "orgao": "Grupo de Câmaras de Direito Civil", "situacao": "Vigente", "obs": "\"Os integrantes do Grupo de Câmaras de Direito Civil, reunidos em sessão ordinária ocorrida em 8-10-2014, aprovaram o seguinte Enunciado, pertinente a matéria de cálculo de benefício de previdência privada: · REDAÇÃO ORIGINAL, PUBLICADA NO DJE N. 2050, DISPONIBILIZADO EM 10-2-2015", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "I", "ord": 1, "texto": "Nos contratos bancários, com exceção das cédulas e notas de crédito rural, comercial e industrial, não é abusiva a taxa de juros remuneratórios superior a 12 % (doze por cento) ao ano, desde que não ultrapassada a taxa média de mercado à época do pacto, divulgada pelo Banco Central do Brasil.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmaras de Direito Comercial, reunidos em Sessão ordinária ocorrida em 13 p.p., homologaram os seguintes enunciados pertinentes a matérias de natureza comercial, especialmente bancária.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "II", "ord": 2, "texto": "No período da inadimplência os juros remuneratórios são devidos na forma da Súmula 296, do Superior Tribunal de Justiça.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "III", "ord": 3, "texto": "A comissão de permanência é admitida nos contratos bancários, exceto nas cédulas e notas de crédito rural, comercial e industrial, desde que contratada e limitada à soma dos encargos remuneratórios e moratórios: a) juros remuneratórios à taxa média de mercado, não podendo ultrapassar o percentual contratado para o período de normalidade da operação; b) juros moratórios até o limite de 12% ao ano; e c) multa contratual limitada a 2% sobre o valor da prestação.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmaras de Direito Comercial, reunidos em sessão ordinária ocorrida em 11/05/11, homologaram a alteração do enunciado III do Grupo de Câmaras de Direito Comercial. A nova redação do enunciado passa a ser a seguinte: · NOVA REDAÇÃO, PUBLICADA NO DJE N. 1.174, DISPONIBILIZADO EM 9-6-2011", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "IV", "ord": 4, "texto": "Na aplicação da taxa média de mercado, apurada pelo Banco Central do Brasil, serão observados os princípios da menor onerosidade ao consumidor, da razoabilidade e da proporcionalidade.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "V", "ord": 5, "texto": "O limite de 2% para a multa moratória em relações de consumo não se aplica a contratos celebrados antes da vigência da Lei n. 9.298/1996.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmaras de Direito Comercial, reunidos em sessão ordinária ocorrida em 08/06/11, homologaram a alteração do enunciado V do Grupo de Câmaras de Direito Comercial. A nova redação do enunciado passa a ser a seguinte: · NOVA REDAÇÃO, PUBLICADA NO DJE N. 1.174, DISPONIBILIZADO EM 9-6-2011", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "VI", "ord": 6, "texto": "A Taxa Referencial (TR) e a Taxa de Juros de Longo Prazo (TJLP) podem ser utilizadas como fatores de correção monetária em contratos bancários, desde que expressamente pactuadas.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Florianópolis, 19 de dezembro de 2006. · PUBLICADO NO DIÁRIO DA JUSTIÇA ELETRÔNICO N. 119, DE 8 DE JANEIRO DE 2007.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "VII", "ord": 7, "texto": "A cobrança antecipada do valor residual garantido (VRG) não descaracteriza o contrato de arrendamento mercantil.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmaras de Direito Comercial, reunidos em Sessão ordinária ocorrida em 09 p.p., homologaram o seguinte enunciado: · Florianópolis, 14 de maio de 2007. · PUBLICAÇÃO NO DIÁRIO DA JUSTIÇA ELETRÔNICO N. 205 PÁG 01 DATA:.16.05.2007.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "VIII", "ord": 8, "texto": "É ilegal o emprego da Tabela Price nos contratos de mútuo firmados sob o regime do Sistema Financeiro da Habitação, na medida em que implica capitalização de juros.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmaras de Direito Comercial, reunidos em Sessão ordinária ocorrida em 13 p.p., homologaram o seguinte enunciado: · Florianópolis, 15 de junho de 2007. · PUBLICAÇÃO NO DIÁRIO DA JUSTIÇA ELETRÔNICO N. 227 PÁG 01 DATA:.18.06.2007.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "IX", "ord": 9, "texto": "Não se justifica a conversão da busca e apreensão, intentada com base no DL n. 911 de 1/09/1969, em ação de depósito, sendo facultado ao credor, todavia, postular o prosseguimento do feito na forma de execução com base no art. 5º do Diploma em questão, preservado o andamento das demandas nas quais já houve a conversão e a citação do devedor.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmaras de Direito Comercial, reunidos em Sessão ordinária ocorrida em 8 p.p., homologaram o seguinte enunciado: · Florianópolis, 09 de agosto de 2007. · PUBLICAÇÃO NO DIÁRIO DA JUSTIÇA ELETRÔNICO N. 268 PÁG 01 DATA:.14.08.2007.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "X", "ord": 10, "texto": "É possível a utilização da Taxa Referencial (TR) no cálculo da correção monetária do saldo devedor de contratos firmados no âmbito do Sistema Financeiro da Habitação (SFH), desde que previsto o reajuste com base nos mesmos índices aplicados aos saldos das cadernetas de poupança.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmaras de Direito Comercial, reunidos em Sessão ordinária ocorrida em 10 p.p., homologaram o seguinte enunciado: · Florianópolis, 11 de outubro de 2007. · PUBLICAÇÃO NO DIÁRIO DA JUSTIÇA ELETRÔNICO N. 311 PÁG 01DATA:.16.10.2007.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "XI", "ord": 11, "texto": "Em demanda cautelar de exibição de documentos, falta interesse de agir àquele que não comprova ter realizado requerimento formal de fornecimento de dados societários junto à companhia, exceto se a necessidade do ingresso em juízo, em casos concretos excepcionais, for inequivocamente comprovada por outro meio.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmaras de Direito Comercial, reunidos em Sessão ordinária ocorrida em 09 p.p., homologaram os seguintes enunciados:", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "XII", "ord": 12, "texto": "No requerimento formal de fornecimento de dados societários perante as companhias, somente é indispensável o pagamento do custo do serviço nas hipóteses em que a empresa custodiadora dos documentos solicitados o exige e confere oportunidade adrede para que o solicitante recolha o valor por ela indicado.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Publicados no Diário da Justiça Eletrônico n. 947, pg. 1, disponibilizado em 21-6-2010.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "XIII", "ord": 13, "texto": "Resta positivada a mora, em alienação fiduciária ou arrendamento mercantil, ainda que a correspondência encaminhada para o endereço do contrato tenha sido devolvida com a informação \"mudou-se\" ou \"inexistente\".", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Publicado nos DJe n. 3004, 3005 e 3006, p. 01 de 19, 20 e 21 de fevereiro de 2019", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "XIV", "ord": 14, "texto": "O ato do fedatário certificando o recebimento de telegrama no endereço do devedor, comprova a mora para o fim de ajuizamento de ação de busca e apreensão ou de reintegração de posse com suporte em contrato de alienação fiduciária ou arrendamento mercantil.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Vigente", "obs": "Publicado nos DJe n. 3004, 3005 e 3006, p. 01 de 19, 20 e 21 de fevereiro de 2019", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Comercial", "n": "XV", "ord": 15, "texto": "No sistema Eproc, excepcionalmente, admite-se o recolhimento do preparo até o dia útil seguinte ao da interposição do recurso.", "materia": "", "orgao": "Grupo de Câmaras de Direito Comercial", "situacao": "Cancelado", "obs": "Publicado nos Dje n. 3374, 3375 e 3376 p. 01 dos dias 25, 26 e 27 de agosto de 2020. CANCELADO, conforme deliberado na sessão do dia 11/11/2020.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "I", "ord": 1, "texto": "Governador, Secretário de Estado ou qualquer outra autoridade detentora de prerrogativa de foro, não é parte legítima para responder a mandado de segurança quando não for responsável direto pela prática do ato impugnado ou por sua correção.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmaras de Direito Público, reunidos em Sessão Ordinária ocorrida em 14/05/2014, homologaram o seguinte Enunciado: · Publicado na página n. 1 do Diário da Justiça Eletrônico n. 1894, disponibilizado em 17 de junho de 2014.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "II", "ord": 2, "texto": "Deferida a antecipação da tutela para a assistência à saúde e sobrevindo a morte do paciente no curso do processo, a sentença a ser proferida é de extinção com base no art. 267, IX, e art. 462, ambos do CPC, operando-se a sucumbência a partir do princípio da causalidade. A tutela antecipada cessa nesse momento, preservados seus efeitos pretéritos.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmara de Direito Público, reunidos em Sessão Ordinária ocorrida em 09/07/2014, homologaram o seguinte Enunciado: · Publicado na página n. 1 do Diário da Justiça Eletrônico n. 1937, disponibilizado em 18 de agosto de 2014.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "III", "ord": 3, "texto": "Ainda que o segurado tenha exercido atividade laboral e percebido salário, não cabe o desconto ou a compensação de valores pagos pelo INSS, no mesmo período, a título de auxílio-doença acidentário concedido judicialmente com efeito pretérito.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmara de Direito Público, reunidos em Sessão Ordinária ocorrida em 13/08/2014, homologaram o seguinte Enunciado: · Publicado na página n. 1 do Diário da Justiça Eletrônico n. 1958, disponibilizado em 16 de setembro de 2014.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "IV", "ord": 4, "texto": "A Súmula vinculante n. 13 refere-se a situações afrontosas à Constituição da República, especialmente por inobservância aos princípios da moralidade, da eficiência e da impessoalidade no âmbito da Administração Pública, daí porque há necessidade, em cada caso concreto, de estar configurada essa eiva para que se caracterize a prática de nepotismo, que claramente não ocorre quando inexiste vínculo de subordinação hierárquica entre a pessoa nomeada e aquela que causaria a incompatibilidade, tampouco quando não se verifica influência direta ou indireta do parente na indicação para o cargo.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmara de Direito Público, reunidos em Sessão Ordinária ocorrida em 08/07/2015, homologaram o seguinte Enunciado: · Publicado na página n.1 do Diário da Justiça Eletrônico n. 2157, disponibilizado em 21 de julho de 2015.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "V", "ord": 5, "texto": "Julgado improcedente o pedido do autor em ações acidentárias movidas em desfavor do INSS, não responde o Estado de Santa Catarina pelo ressarcimento de honorários periciais adiantados pela autarquia, nos termos do art. 8º, § 2º da Lei n. 8.620/93, ou de quaisquer outras verbas decorrentes do processo, pois o autor (segurado) litiga sob a isenção de que trata o art. 129, parágrafo único, da Lei n. 8.213/91, que não se confunde com as regras da assistência judiciária gratuita ou da gratuidade da justiça. Enunciado revogado por deliberação unânime, dos Desembargadores do Grupo de Câmaras de Direito Público, na sessão do dia 27-10-2021. Comunicado publicado no Diário de Justiça Eletrônico n. 3658, p.1, de 04 de novembro de 2021.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Revogado", "obs": "Os integrantes do Grupo de Câmara de Direito Público, reunidos em Sessão Ordinária ocorrida em 12/08/2015, homologaram o seguinte Enunciado: · Publicado na página n.1 do Diário da Justiça Eletrônico n. 2197, disponibilizado em 15 de setembro de 2015.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "VI", "ord": 6, "texto": "A implantação de sistema remuneratório, na forma de subsídio, por força de diversas Leis Complementares para várias categorias funcionais da área da segurança pública estadual, não traz consigo qualquer mácula, a menos que ocorra redução do valor nominal global percebido pelo servidor, situação verificada caso a caso, para resguardar a irredutibilidade de vencimentos.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmara de Direito Público, reunidos em Sessão Ordinária ocorrida em 09/09/2015, homologaram o seguinte Enunciado: · Publicado na página n.1 do Diário da Justiça Eletrônico n. 2221, disponibilizado em 20 de outubro de 2015.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "VII", "ord": 7, "texto": "A fixação de subteto remuneratório escalonado para a carreira de auditor fiscal do Estado de Santa Catarina, consoante estabelecido na Lei Complementar Estadual n. 442/2009, não ofende ao art. 23, III, da Constituição do Estado de Santa Catarina, na medida em que a Emenda Constitucional Estadual 47/08, ao fixar o teto remuneratório, não determinou que todos alcançariam, de imediato, a remuneração máxima por ela prevista, condicionando-a a escalonamento hierárquico.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmara de Direito Público, reunidos em Sessão Ordinária ocorrida em 14/10/2015, homologaram o seguinte Enunciado: · Publicado na página n.1 do Diário da Justiça Eletrônico n. 2231, de 05 de novembro 2015.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "VIII", "ord": 8, "texto": "Nas ações em que a Celesc for demandada por eventuais prejuízos causados ao fumicultor em decorrência da interrupção do fornecimento de energia elétrica, somente será admissível o julgamento antecipado quando a concessionária não oferecer defesa, ou apresentar contestação genérica, sem contestar, pontual e objetivamente, o laudo técnico extrajudicial elaborado pelo autor da ação ou, ainda, quando não formular a produção de provas de forma específica e com dedução expressa da finalidade. A dilação probatória, quando pertinente, deverá ser realizada na fase de conhecimento, para prolação de sentença líquida.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmara de Direito Público, reunidos em Sessão Ordinária ocorrida em 14/10/2015, homologaram o seguinte Enunciado: · Publicado na página n.1 do Diário da Justiça Eletrônico n. 2231, de 05 de novembro 2015.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "IX", "ord": 9, "texto": "Ao conceder a tutela provisória, em ação voltada para concessão de medicamentos, o magistrado fixará prazo razoável para o cumprimento da medida, sob pena de sequestro da quantia necessária à efetivação do comando judicial, afastada a imposição de multa concorrente.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Os integrantes do Grupo de Câmaras de Direito Público, reunidos em sessão ordinária ocorrida em 11/05/2016, aprovaram o seguinte Enunciado: · Publicado na página n.1 do Diário da Justiça Eletrônico n. 2355, disponibilizado em 23 de maio de 2016.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "X", "ord": 10, "texto": "Deve ser promovida a conciliação entre a oferta de educação infantil em período integral e parcial a partir da demonstração da efetiva necessidade de todos aqueles que compõe o núcleo familiar de que participa o (a) infante, analisando-se o caso concreto.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado na página n.1 do Diário da Justiça Eletrônico n. 2678, de 29 de setembro 2017.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XI", "ord": 11, "texto": "Nos termos da 1ª Conclusão do Grupo de Câmaras de Direito Público (DJE n. 2.023, p. 1-2, de 17-12-2014), ratifica-se que são da competência recursal do Tribunal de Justiça as ações cujas petições iniciais tenham sido protocoladas até 23 de junho de 2015, ressalvados os casos anteriores a essa data em que houve inequívoca adoção do rito da Lei n. 12.153, de 22 de dezembro de 2009.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XII", "ord": 12, "texto": "A competência dos Juizados Especiais da Fazenda Pública é absoluta e deve ser aferida em face do valor da causa (até 60 salários mínimos, nos termos do art. 2º, caput, da Lei n. 12.153, de 22 de dezembro de 2009, tendo como base o valor vigente à época do ajuizamento da ação).", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XIII", "ord": 13, "texto": "Cabe ao juiz com competência fazendária cumulativa (comum e especial), ao despachar a inicial, definir claramente se é aplicável o rito da Lei n. 12.153, de 22 de dezembro de 2009, evitando controvérsias quanto à competência. Se ignorada a medida, ainda assim a atribuição absoluta do Sistema dos Juizados Especiais, se for o caso, preponderará, devendo o tema ser abordado mesmo de ofício pelo Tribunal de Justiça na hipótese de os autos equivocadamente lhe serem remetidos.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XIV", "ord": 14, "texto": "Nos termos da 3ª Conclusão do Grupo de Câmaras de Direito Público (DJE n. 2.023, p. 1-2, de 17-12-2014), bem como do § 3º do art. 292 do Código de Processo Civil, o magistrado poderá corrigir de ofício o valor atribuído à causa com a finalidade de aferir a competência dos Juizados Especiais da Fazenda Pública.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XV", "ord": 15, "texto": "As ações sem conteúdo econômico imediato, não havendo tampouco critério objetivo para valoração da causa, devem ser apreciadas no juízo comum. Enunciado revogado no julgamento do Conflito de Competência Cível n. 50079694020208240000, na sessão de 22-09-2021, do Grupo de Câmaras de Direito Público. Comunicado publicado no Diário de Justiça Eletrônico n. 3635, p.1, de 29 de setembro de 2021.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Revogado", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XVI", "ord": 16, "texto": "É o valor da causa, não a extensão da procedência, que define a competência dos Juizados Especiais da Fazenda Pública e das Turmas Recursais.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XVII", "ord": 17, "texto": "Conforme 4ª Conclusão do Grupo de Câmaras de Direito Público (DJE n. 2.023, p. 1-2, de 17-12-2014), é possível o processamento de causas que versem sobre o fornecimento de medicamentos ou de tratamento médico (inclusive cirúrgico), desde que se comprove seguramente a equivalência econômica da pretensão com a alçada dos Juizados Especiais da Fazenda Pública.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XVIII", "ord": 18, "texto": "Compete ao Tribunal de Justiça analisar e julgar os recursos derivados de causas processadas nas Varas da Infância e Juventude (autônomas ou com competência cumulativa) quando dirigidas contra a Fazenda Pública.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XIX", "ord": 19, "texto": "As ações de acidente do trabalho apresentadas em relação ao Instituto Nacional do Seguro Social não comportam deslocamento aos Juizados Especiais da Fazenda Pública e Turmas de Recurso, pois a Justiça Estadual ordinária, no caso, atua em cumprimento de mandamento constitucional (Súmulas n. 235 e 501 e Tema n. 414 do STF), além de a Fazenda Pública Federal não estar entre os legitimados passivos perante a Lei n. 12.153, de 22 de dezembro de 2009 (art. 5º, inc. II).", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XX", "ord": 20, "texto": "Os pleitos atinentes a concurso público, por não ostentarem expressão patrimonial mensurável e por terem o respectivo valor da causa aferido de forma subjetiva por simples estimativa, não se enquadram na hipótese prevista no art. 2º, caput, da Lei n. 12.153/2009 (Grupo de Câmaras de Direito Público, CC n. 2011.064597-0, rel. Des. Luiz Cézar Medeiros, j. em 14-8-2013); assim, devem tramitar perante o juízo comum. Mas podem ser da competência do Juizado Especial as demandas que, mesmo tendo como causa de pedir concurso público, apenas abordam aspectos patrimoniais (como indenização por danos morais ou vencimentos).", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XXI", "ord": 21, "texto": "As causas descritas no art. 2º, § 1º, da Lei n. 12.153, de 22 de dezembro de 2009 (ações de mandado de segurança, de desapropriação, de divisão e demarcação, populares, por improbidade administrativa, execuções fiscais, demandas sobre direitos ou interesses difusos e coletivos; causas sobre bens imóveis dos Estados, Distrito Federal, Territórios e Municípios, autarquias e fundações públicas a eles vinculadas; que tenham como objeto a impugnação da pena de demissão imposta a servidores públicos civis ou sanções disciplinares aplicadas a militares) não são admitidas nos Juizados Especiais da Fazenda Pública e Turmas Recursais; caso verificada a situação, devem ser imediatamente deslocadas ao juízo comum ou ao Tribunal de Justiça.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XXII", "ord": 22, "texto": "Ratifica-se a 5ª Conclusão do Grupo de Câmaras de Direito Público (DJE n. 2.023, p. 1-2, de 17-12-2014) quanto à aferição individualizada dos pedidos na hipótese de litisconsórcio ativo facultativo, independentemente de o valor da causa superar a alçada de 60 (sessenta) salários mínimos.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XXIII", "ord": 23, "texto": "A necessidade de realização de perícia não afasta a competência dos Juizados Especiais da Fazenda Pública, consoante já firmado na 6ª Conclusão do Grupo de Câmaras de Direito Público (DJE n. 2.023, p. 1-2, de 17-12-2014).", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XXIV", "ord": 24, "texto": "O cumprimento de sentença, no contexto do Juizado Especial da Fazenda Pública, deve circunscrever-se aos seus próprios julgados, à exceção da possibilidade da execução de sentença coletiva pelo substituído.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XXV", "ord": 25, "texto": "É dado ao membro de Turma de Recursos, ao receber autos redirecionados pelo Tribunal de Justiça, havendo dúvida fundada quanto à efetiva atribuição do Sistema de Juizados Especiais da Fazenda Pública, mediante fundamentação específica, restituir o feito ao então Desembargador relator para que haja ou não ratificação da decisão quanto à competência.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Vigente", "obs": "Publicado no Diário da Justiça Eletrônico n. 3024, de 21 de março 2019.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XXVI", "ord": 26, "texto": "Se a decisão exequenda transitou em julgado em momento posterior à publicação da decisão que declarou inconstitucional o art. 5º da Lei n. 11.960/09 para correção monetária (Tema n. 810 do STF), ocorrida em 20.11.17, o título executivo será inexigível no ponto, devendo ser adotada em cumprimento de sentença a legislação vigente em relação aos consectários legais (art. 525, § 12, e art. 535, § 5º, ambos do CPC/15). Comunicado de revogação publicado no Diário de Justiça Eletrônico n. 3727 p.1, de 07 de março de 2022.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Revogado", "obs": "Publicado no Diário da Justiça Eletrônico n. 3447, de 11 de dezembro de 2020.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Grupo de Câmaras de Direito Público", "n": "XXVII", "ord": 27, "texto": "Se a decisão exequenda transitou em julgado em momento anterior à publicação da decisão que declarou inconstitucional o art. 5º da Lei n. 11.960/09 para correção monetária (Tema n. 810 do STF), ocorrida em 20.11.17, é preciso respeitar a coisa julgada já operada (Tema n. 905 do STJ), sendo possível a sua alteração somente por recurso próprio ou ação rescisória, no prazo do § 8º do art. 535 do CPC/15. Enunciado parcialmente revogado, de acordo com o posicionamento adotado, na sessão de 25-8-2021, no julgamento dos processos (AR 50090046920198240000; AR 5023919-89.2020.824.0000; AR 5027701-70.2021.8.24.0000; AR 50337826920208240000; 50289014920208240000; AR 50176422320218240000; AR 50082474120208240000; AR 50366692620208240000; AR 50007342220208240000), passando a vigorar com a seguinte redação: Enunciado XXVII Se a decisão exequenda transitou em julgado em momento anterior à publicação da decisão que declarou inconstitucional o art. 5º da Lei n. 11.960/09 para correção monetária (Tema n. 810 do STF), ocorrida em 20.11.17, é preciso respeitar a coisa julgada já operada (Tema n. 905 do STJ). Comunicado publicado no Diário de Justiça Eletrônico n. 3635, p.1, de 29 de setembro de 2021. Comunicado de revogação publicado no Diário de Justiça Eletrônico n. 3727, p.1, de 07 de março de 2022.", "materia": "", "orgao": "Grupo de Câmaras de Direito Público", "situacao": "Revogado", "obs": "Publicado no Diário da Justiça Eletrônico n. 3447, de 11 de dezembro de 2020.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Câmara de Recursos Delegados", "n": "I", "ord": 1, "texto": "Em se tratando de Conflito de Competência envolvendo Juízes de Unidades Jurisdicionais de 1º Grau, quando não houver controvérsia acerca da natureza da matéria de fundo, é competente para dirimir o conflito uma das Câmaras isoladas, com atuação na respectiva área do Direito em que se insere a ação.", "materia": "", "orgao": "Câmara de Recursos Delegados", "situacao": "Cancelado", "obs": "Publicado nos Dje ns. 4467, 4469 e 4470, nos dias 09, 11 e 14 de abril de 2025. CANCELADO, conforme deliberado na sessão do dia 22/04/2025.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Câmara de Recursos Delegados", "n": "II", "ord": 2, "texto": "Caracteriza-se como ação de natureza tipicamente civil, ainda que envolva instituição financeira subordinada à fiscalização do Banco Central do Brasil, aquela em que o demandante visa obter a declaração de inexigibilidade de débito, com ou sem pedido indenizatório, se não há discussão acerca dos termos de contrato bancário, de modo que não atrai a competência da Vara/Juízo Especializado.", "materia": "", "orgao": "Câmara de Recursos Delegados", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Câmara de Recursos Delegados", "n": "III", "ord": 3, "texto": "Compete às varas cíveis processar e julgar ação de imissão de posse proposta por arrematante de bem imóvel, após a consolidação da propriedade ao credor fiduciário, contra devedor fiduciante que, não obstante tenha sido intimado dos atos de expropriação extrajudicial, nos moldes da Lei n. 9.514/97, recusa-se a desocupar o bem, eis que a matéria discutida, em casos tais, é de natureza eminentemente civil, a dispensar a incursão na análise de contrato bancário para a solução do imbróglio.", "materia": "", "orgao": "Câmara de Recursos Delegados", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Câmara de Recursos Delegados", "n": "IV", "ord": 4, "texto": "Por terem índole material, são absolutas as competências internas dos órgãos fracionários dos tribunais, motivo pelo qual somente se cogita a prevenção acaso existente conflito entre Câmaras materialmente competentes para a análise do feito.", "materia": "", "orgao": "Câmara de Recursos Delegados", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Câmara de Recursos Delegados", "n": "V", "ord": 5, "texto": "As empresas securitizadoras de crédito, embora não se enquadrem no conceito de instituição financeira propriamente dita, previsto no art. 17 da Lei n. 4.595/64, estão subordinadas às mesmas normas e praticam atividade típica do mercado financeiro, razão pela qual devem assim ser equiparadas para fins de definição da competência das Varas de Direito Bancário.", "materia": "", "orgao": "Câmara de Recursos Delegados", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Câmara de Recursos Delegados", "n": "VI", "ord": 6, "texto": "A distribuição de competências entre unidades jurisdicionais de Direito Civil e Bancário observa, preponderantemente, o critério ex ratione materiae, definindo-se a partir da leitura da causa de pedir e do pedido. Em se tratando de ações envolvendo a temática dos Cartões de Crédito com Reserva de Margem Consignável - RMC: (I) se a causa de pedir e o pedido envolverem a inexistência de relação jurídica por total ausência de contratação, a competência recai sobre as unidades de Direito Civil, não havendo incursão em matéria de índole bancária; e (II) se, por outro lado, a causa de pedir e o pedido abrangerem situações fático-jurídicas que levaram à subscrição de pacto bancário diverso do pretendido, tendo-se por indevida a reserva de margem consignada no lugar do empréstimo objetivado, desponta a competência das unidades de Direito Bancário.", "materia": "", "orgao": "Câmara de Recursos Delegados", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Câmara de Recursos Delegados", "n": "VII", "ord": 7, "texto": "Mostra-se descabida a modificação de competência de natureza absoluta, ainda que haja conexão ou continência com demanda em trâmite em unidade jurisdicional diversa (art. 54 do Código de Processo Civil/2015).", "materia": "", "orgao": "Câmara de Recursos Delegados", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "1", "ord": 1, "texto": "É legítima a exclusão de vantagens pecuniárias da base de cálculo de horas extras e noturnas de servidores públicos, por expressa vedação das leis que as instituíram. (Processo: 0000001-61.2012.8.24.9009 - Sessão da Turma de Uniformização do dia 29/04/2013 - Disponibilizado no DJE n. 1689, de 07/08/2013, página 485).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "2", "ord": 2, "texto": "Os juros de mora, na indenização por dano moral, correm a partir da data do arbitramento.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Revogado", "obs": "Processo: 0000002-46.2012.8.24.9009)", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "3", "ord": 3, "texto": "O terço constitucional de férias anuais dos membros do magistério público do Estado de Santa Catarina incide tão somente sobre 30 (trinta) dias e não sobre os 60 (sessenta) dias mencionado no art. 93, caput, da Lei Estadual n. 6.844/1986.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": "Disponibilizado no DJE n. 1861, de 30/04/2014, página 428) · Processo: 0000034-17.2013.8.24.9009 - Sessão da Turma de Uniformização do dia 28/04/2014 -", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "4", "ord": 4, "texto": "Por expressa previsão legal, não é devido o auxílio alimentação aos policiais militares do Estado de Santa Catarina no período de gozo de licença especial equiparada à licença-prêmio do servidor civil.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": "Processo: 0000024-70.2013.8.24.9009 - Sessão da Turma de Uniformização do dia 28/04/2014 - Disponibilizado no DJE n. 1861, de 30/04/2014, página 428)", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "5", "ord": 5, "texto": "No caso de passagem do policial militar à inatividade, a indenização da licença especial equiparada à licença-prêmio do servidor civil tem como base o valor bruto da remuneração do último mês anterior à inativação e não o soldo.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": "Disponibilizado no DJE n. 1861, de 30/04/2014, página 428) · Processo: 0000033-32.2013.8.24.9009 - Sessão da Turma de Uniformização do dia 28/04/2014 -", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "6", "ord": 6, "texto": "Horas extras no regime jurídico a que estão submetidos os Militares do Estado de Santa Catarina são todas aquelas que excedem a carga horária de 40 horas semanais, conforme estabelece o §1º do art. 3º da Lei Complementar Estadual n. 137/1995.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": "Processo: 0000020-62.2015.8.24.9009 - Sessão da Turma de Uniformização do dia 28/09/2015 - Disponibilizado no DJE n. 2208, de 30/09/2015, página 378)", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "7", "ord": 7, "texto": "Os reflexos da indenização de estímulo operacional por horas extras e adicional noturno recebidos por militares do Estado de Santa Catarina no mês de dezembro incidem no cálculo da gratificação natalina conforme art. 1º da Lei Estadual 7.130/87.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": "Disponibilizado no DJE n. 2208, de 30/09/2015, página 378) · Processo: 0000017-10.2015.8.24.9009 - Sessão da Turma de Uniformização do dia 28/09/2015 -", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "8", "ord": 8, "texto": "Na hipótese de descumprimento de contrato de transporte aéreo, os juros de mora sobre a verba indenizatória de dano moral, em decorrência de extravio de bagagem, incidem a partir da citação.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": "Processo: 0000039-68.2015.8.24.9009 - Sessão da Turma de Uniformização do dia 28/09/2015 - Disponibilizado no DJE n. 2208, de 30/09/2015, página 378)", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "9", "ord": 9, "texto": "Nos termos dos artigos 3º e 4º da Lei 12.153/09, cabe recurso contra decisão interlocutória apenas e tão somente quando houver decisão concessiva da medida pleiteada.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": "Processo n. 0000008-77.2017.8.24.9009 - Sessão da Turma de Uniformização do dia 19/05/2017 - Disponibilizado no DJE n. 2611, de 23/06/2017, página 2)", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "10", "ord": 10, "texto": "Na ação de cobrança de cheque, os juros da mora são contados a partir da primeira apresentação.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": "Processo n. 0000042-23.2015.8.24.9009 - Sessão da Turma de Uniformização do dia 18/08/2017 - Disponibilizado no DJE n. 2656, de 25/08/2017, página 3)", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "11", "ord": 11, "texto": "No Sistema dos Juizados Especiais Cíveis e da Fazenda Pública os prazos serão contados em dias úteis.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": "Processo n. 0000018-24.2017.8.24.9009 - Sessão da Turma de Uniformização do dia 18/08/2017 - Disponibilizado no DJE n. 2680, de 03/10/2017, página 1)", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "12", "ord": 12, "texto": "O mero descumprimento contratual de cobertura securitária decorrente de morte não gera dano moral in re ipsa, ressalvada a demonstração da sua configuração no caso concreto.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": "Processo n. 0000021-76.2017.8.24.9009, Sessão da Turma de Uniformização do dia 25/06/2018 - Disponibilizado no DJE n. 2886, de 17/08/2018, p. 1)", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "13", "ord": 13, "texto": "O Juizado Especial é competente para a discussão dos contratos bancários que tratam da reserva de margem consignável previstos na Lei n. 10.820/2003.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "14", "ord": 14, "texto": "Observados os termos da Lei n. 10.820/03 a da Instrução Normativa n. 28/2008-INSS, é válido o contrato de cartão de crédito consignado com autorização para desconto em benefício previdenciário, não havendo dano moral presumível no caso de sua contratação com inobservância daquelas regras.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "15", "ord": 15, "texto": "O marco inicial para o cômputo do período aquisitivo de férias dos Policiais Militares é a data do seu ingresso no serviço público.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "16", "ord": 16, "texto": "Demandas em que o agente público aposentado pleiteie verbas relacionadas ao período de atividade devem ser propostas em face do ente político em cuja estrutura se inseria o cargo por si ocupado e não contra os institutos próprios de previdência, que não detêm legitimidade passiva ad causam, matéria que, muito embora ostente matiz processual, deve ser conhecida, na hipótese, ante a peculiar relevância do tema subjacente, em homenagem aos princípios da celeridade e da segurança jurídica.", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "17", "ord": 17, "texto": "Em observância aos Temas 810 e 905 do Supremo Tribunal Federal e do Superior Tribunal de Justiça, respectivamente, o índice de correção monetária a ser aplicado nas condenações judiciais referentes a servidores públicos, a partir de janeiro de 2001, é o Índice Nacional de Preços ao Consumidor Amplo Especial - IPCA-E. (Processo 0000023- 75.2019.8.24.9009, j. em 09/12/2019).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "18", "ord": 18, "texto": "O marco inicial para o pagamento do adicional de insalubridade para os servidores do Município de Pouso Redondo é a data da exposição do servidor à atividade insalubre, limitado ao quinquênio que antecede o ajuizamento da ação. (Pedido de Uniformização n. 0000032-03.2020.8.24.9009, julgado em 09/10/2020).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "19", "ord": 19, "texto": "O abono de permanência de que trata o art. 40, § 19, da Constituição Federal, assegurado aos servidores civis (Repercussão Geral, Tema 888, STF) não se aplica aos servidores militares do Estado de Santa Catarina, sujeitos a regime jurídico próprio, ante a inexistência de legislação estadual específica. (Pedido de Uniformização n. 0000006- 05.2020.8.24.9009, julgado em 09/10/2020).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "20", "ord": 20, "texto": "O pagamento do benefício denominado auxílio-atleta concedido na vigência da Lei n. 3.448/97 não pode ser condicionado ao cumprimento das exigências estabelecidas pela Lei n. 6.861/2017, ambas do Município de Criciúma, sendo garantido aos beneficiários já contemplados o percebimento pelo prazo estabelecido naquela lei. (Pedido de Uniformização n. 0000026-93.2020.8.24.9009, julgado em 09.11.2020).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "21", "ord": 21, "texto": "A gratificação de incentivo à regência de classe prevista no artigo 59, § 1º, da LCM n. 130/01, do Município de Chapecó, é devida aos professores readaptados mesmo que não ministrem aulas diretamente aos educandos, porque o rol é exemplificativo e não há vedação legal ao pagamento durante a readaptação. (Pedidos de Uniformização n. 0000005-83.2021.8.24.9009, e n. 0000052-91.2020.8.24.9009, julgados em 08/03/2021).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "22", "ord": 22, "texto": "A conversão em pecúnia do período de 15 (quinze) dias de férias excedentes dos servidores públicos do magistério local é possível desde que expressamente prevista em legislação municipal. (Pedido de Uniformização n. 0000011-90.2021.8.24.9009, julgado em 12/04/2021).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "23", "ord": 23, "texto": "Nas demandas propostas perante os juizados especiais fazendários que objetivem o fornecimento de medicamentos ou procedimentos não padronizados pelo SUS, a União obrigatoriamente fará parte do polo passivo na qualidade de litisconsorte necessário. (Enunciado aprovado apud acta, art. 66-M, RITR).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "24", "ord": 24, "texto": "O vale alimentação previsto na LCM n. 2.186/96 é devido aos servidores públicos de Lages durante licença para tratamento de saúde. (PUIL n. 0000035-21.2021.8.24.9009, j. em 12.07.2021).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "25", "ord": 25, "texto": "Agente comunitário de saúde e/ou agente administrativo lotado em pronto atendimento que não se submete ao contato permanente com agentes biológicos descritos no anexo 14 da NR 15 do Ministério da Saúde não fazendo jus ao adicional de insalubridade. A conclusão do perito judicial, nessa situação, não vincula a atuação do magistrado. (PUIL 0000043-95.2021.8.24.9009, sessão de 13/09/2021, com redação dada nos ED 0000043-95.2021.8.24.9009/50000, de 29/11/2021).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": "Nova redação.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "26", "ord": 26, "texto": "A inscrição indevida em dívida ativa, por si só, não é fator suficiente para a caracterização do abalo moral, por não ser in re ipsa. (PUIL n. 0000021-37.2021.8.24.9009, sessão de 13/09/2021).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "27", "ord": 27, "texto": "O ajuizamento de ação de execução fiscal decorrente de indevida inscrição em dívida ativa é fator suficiente para a caracterização do dano moral. (PUIL n. 0000021- 37.2021.8.24.9009, sessão de 13/09/2021).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "28", "ord": 28, "texto": "Não é atípica, em razão do princípio constitucional da não autoincriminação, a conduta daquele que desobedece à ordem de parada dada no exercício de atividade ostensiva de policiamento, em decorrência da suspeita da prática de crimes, configurando-se, nesta hipótese, o delito previsto no art. 330 do Código Penal. (PUIL n. 0000062- 04.2021.8.24.9009, sessão de 29/11/2021).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "29", "ord": 29, "texto": "Inexistindo vinculação na norma local, a ausência da atividade exercida pelo servidor público na classificação indicada na Norma Regulamentar nº 15, Anexo 14, do Ministério do Trabalho, não é impedimento para o reconhecimento da insalubridade.” (PUIL n. 0000036-06.2021.8.24.9009, sessão de 29/11/2021).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "30", "ord": 30, "texto": "A percepção do adicional de insalubridade pelo servidor público do estado de Santa Catarina, para conversão do tempo de serviço especial, possui presunção juris tantum da prática de atividade em ambiente insalubre, podendo ser ilidida com a juntada pelo estado, durante a instrução, do laudo técnico de condições ambientais do trabalho - LTCAT, arts.57 e 58, da lei nº 8.213/91. (PUIL 0000073-33.2021.8.24.9009, sessão de 04/04/2022) Disponibilizado no DJE n. 3757 de 22/04/2022, página 692)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Cancelado", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "31", "ord": 31, "texto": "A gratificação especial fixada no art. 86, inciso VIII, da Lei Complementar n. 117/2011, do Município de Araquari, devida ao servidor que completar 25 (vinte e cinco) anos de efetivo serviço no município, possui natureza indenizatória, motivo pela qual não se submete ao teto constitucional, conforme exceção prevista no parágrafo 11 do art. 37 da Constituição Federal. (PUIL n. 0000049-05.2021.8.24.9009, sessão de 04/04/2022). Disponibilizado no DJE n. 3757, de 22/04/2022, página 692)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "32", "ord": 32, "texto": "Os servidores inativos do magistério público do Estado de Santa Catarina, aposentados na última classe da norma anterior, não possuem direito ao reenquadramento automático na última classe da nova carreira; entretanto, detêm o direito à comprovação, na esfera administrativa, dos requisitos objetivos previstos no art. 12 da LC 688/2015 até a data da sua inativação. (PUIL n. 0000047-35.2021.8.24.9009, sessão do dia 16.05.2022).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "33", "ord": 33, "texto": "Para a concessão de adicional por tempo de serviço aos servidores estáveis do Município de Balneário Camboriú (art. 96 da Lei Municipal nº 1.069/91), e efeitos dela decorrentes, computa-se o tempo de efetivo exercício em cargo comissionado, anterior à investidura no cargo efetivo. (PUIL n. 0000063-86.2021.8.24.9009, sessão do dia 16.05.2022)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "34", "ord": 34, "texto": "A contagem de tempo de serviço e do período aquisitivo de licença-prêmio dos servidores do município de Joinville não foram interrompidas pela fruição de licença premio para tratar de assuntos particulares na vigência da Lei Complementar Municipal n. 21/95. Nesta hipótese, a Lei simplesmente não conferia direito àquela licença. O período aquisitivo em curso quando da transição das Leis Complementares Municipais 21/95 e n. 266/08, deve ser contabilizado para fins de concessão da referida licença. (PUIL n. 0000017-63.2022.8.24.9009, sessão do dia 16.05.2022)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "35", "ord": 35, "texto": "Os servidores públicos do Município de Itaiópolis, que formularam requerimento administrativo antes da vigência da Lei n. 59/2017, detêm direito ao pagamento do adicional por grau de instrução, mesmo quando a graduação tenha data de conclusão anterior ao ingresso no serviço público ou à vigência da Lei n. 17/2012. (PUIL n. 0000039-58.2021.8.24.9009, sessão do dia 16.05.2022)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "36", "ord": 36, "texto": "Os servidores do magistério estadual que desempenham atividades no âmbito administrativo passam a compor o quadro único (civil) e se desvinculam do cargo e da tabela de vencimentos de origem. Assim sendo, o enquadramento deve respeitar a progressão e a tabela previstas para o quadro civil, na Lei Complementar n. 676/2016, não sendo possível mesclar os quadros para aplicar os critérios estabelecidos na Lei n. 1.139/1992. (PUIL n. 0000045-31.2022.8.24.9009, sessão do dia 16.05.2022).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "37", "ord": 37, "texto": "A partir da publicação da Lei Complementar Municipal n. 1.325/2005, os servidores públicos do município de Correia Pinto tem direito ao recebimento do adicional por tempo de serviço (triênio), previsto no artigo 82 da Lei n. 497/93. (PUIL n. 0000091-20.2022.8.24.9009, sessão do dia 29.08.2022)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "38", "ord": 38, "texto": "A gratificação de dedicação exclusiva ao serviço instituída em favor dos motoristas do Município de Guaraciaba, regulamentada pelas Leis Municipais nºs. 1.964/07 e 2.808/15, não ofende os preceitos constitucionais atinentes ao regime remuneratório dos servidores públicos, obstando o pagamento de diferenças estipendiais decorrentes de horas extraordinárias, sob pena da ocorrência de bis in idem. (PUIL n. 0000091-20.2022.8.24.9009, sessão de 31/10/2022).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "39", "ord": 39, "texto": "A expressão \"autoridade policial\" utilizada no art. 69 da Lei n. 9.099/95 não se refere exclusivamente à polícia judiciária, englobando também os demais agentes públicos estatais designados para exercer as funções de autoridade policial, podendo ser policial civil ou militar. (Pedidos de Uniformização n. 0000292-94.2019.8.24.0027, 0003969- 96.2018.8.24.0018 E 0010528-35.2019.8.24.0018, sessão de 16.06.2013).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "40", "ord": 40, "texto": "O pedido de incidência da progressão por mérito e das vantagens agregadas sobre o valor percebido a título de ampliação de carga horária, formulado pelos servidores do Município de Chapecó, não configura revisão do ato de aposentadoria em si e, em se tratando de relação de trato sucessivo, não há prescrição do fundo de direito, atingindo apenas as parcelas anteriores ao quinquênio da propositura da ação. (Pedido de Uniformização n. 5001156-69.2022.8.24.0018, sessão de 16.06.2013).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "41", "ord": 41, "texto": "A renda mensal inicial do servidor que se aposenta com integralidade remuneratória e paridade de vencimentos, de acordo com o regime previdenciário vigente antes da EC n. 103/2019, corresponde ao valor da última remuneração recebida antes da passagem à inatividade. Por isso, não incide correção monetária no cálculo das parcelas da Gratificação de Desempenho e Produtividade Médica (GDPM) de servidores estaduais aposentados com integralidade e paridade remuneratória, de acordo com regras anteriores à vigência da EC n. 103/2019, em razão da vedação de percepção de proventos de aposentadoria superiores à remuneração recebida durante a atividade (art. 40, § 2º, da CF)\". (Pedido de Uniformização n. 5004516-87.2022.8.24.0090, sessão de 16.06.2013).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "42", "ord": 42, "texto": "O art. 11 da Portaria n. 775/2013, do Estado de Santa Catarina, não constitui óbice à progressão funcional do servidor estadual, com base na LC n. 323/2006, no mesmo ano do término do estágio probatório. Tampouco pode ser exigido, para avanço funcional por qualificação ou desempenho, que o servidor tenha obtido anterior progressão por tempo de serviço. (Pedidos de Uniformização ns. 5001224-02.2019.8.24.0090, 5000147-55.2019.8.24.0090 e 5000044-48.2019.8.24.0090, sessão de 21.08.2023)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "43", "ord": 43, "texto": "Não é devido o pagamento de gratificação por aula complementar no período em que membro do magistério estadual estiver afastado em licença para tratamento de saúde. (Pedido de Uniformização ns. 0308536-75.2018.8.24.0090 e 03026965420178240079)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "44", "ord": 44, "texto": "Nas ações em que os servidores cumpram jornada de trabalho 12x36, as horas extraordinárias laboradas a partir da 13ª hora em sábados, domingos e feriados devem ser acrescidas de adicional de 50% (cinquenta por cento). ( Pedido de Uniformização n. 0012097-81.2013.8.24.0018, Relatora Dra. Adriana Bertoncini)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "45", "ord": 45, "texto": "Nas ações de natureza indenizatória extrapatrimonial decorrentes de inscrição indevida em cadastros restritivos de crédito, o prazo prescricional aplicável é trienal, previsto no art. 206, § 3º, V, do Código Civil/02. (Pedido de Uniformização n. 5001684-90.2019.8.24.0024, Relatora Dra. Adriana Bertoncini)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "46", "ord": 46, "texto": "Os agentes penitenciários e agentes de segurança socioeducativos que exerceram funções temporárias anteriormente à Lei Complementar n. 675/2016, fazem jus à contagem do respectivo tempo de serviço para fins de reenquadramento funcional. (Pedido de Uniformização n. 5001655-31.2022.8.24.0090, Relatora Dra. Adriana Bertoncini)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Revogado", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "47", "ord": 47, "texto": "O Município de Lages não pode ser responsabilizado pelo inadimplemento de contrato de vigilância eletrônica e monitoramento de alarmes à distância em unidades de ensino municipais, firmado exclusivamente entre os conselhos de pais e professores e a empresa prestadora do serviço. (Pedido de Uniformização n. 0300702- 82.2015.8.24.0039, Relator Dr. Jaber Farah Filho)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "48", "ord": 48, "texto": "Não é devido, aos servidores estaduais, o pagamento de auxílio-alimentação em período de licença para tratamento de saúde de familiar, conforme previsão do inciso IX do parágrafo 8º do artigo 1º da Lei n. 11.647/2000, alterada pela Lei n. 17.072/17. (Pedido de Uniformização n. 5018440-05.2021.8.24.0090 - Relatora Brigitte Remor de Souza May)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "49", "ord": 49, "texto": "Quando a legislação municipal condicionar o pagamento do adicional de insalubridade à formalização de laudo técnico, o termo inicial para a concessão da benesse é a data de elaboração do laudo administrativo ou pericial que reconhece a exposição a agentes insalubres. (Pedido de Uniformização n. 5007460-55.2020.8.24.0018, Relatora Dra. Margani de Mello).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "50", "ord": 50, "texto": "Existindo divergência entre o grau de insalubridade reconhecido pela administração e aquele efetivamente constatado por perícia judicial das condições do ambiente de trabalho, é devida a complementação do adicional respectivo desde a formalização do laudo pericial administrativo. (Pedido de Uniformização n. 5002574-07.2022.8.24.0062, Relator Dr. Jaber Farah Filho).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "51", "ord": 51, "texto": "O recebimento de aulas excedentes previstas no art. 20, § 2º, da Lei Municipal n. 1.223/2007 é aplicável apenas aos membros do magistério do Município de Jaguaruna que lecionam nas disciplinas de educação física e artes. (Pedido de Uniformização n. 5000533-91.2019.8.24.0282, sessão do dia 15.04.2024).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "52", "ord": 52, "texto": "Havendo previsão em legislação municipal específica, o marco inicial para o pagamento de adicional de periculosidade aos servidores que trabalhem com habitualidade em situações perigosas é a data de vigência da Portaria do MTE que reconheceu a atividade como perigosa, limitado ao quinquênio que antecede o ajuizamento da ação. (Pedidos de Uniformização ns. 0301124-31.2017.8.24.0025/SC, 0301126-98.2017.8.24.0025/SC, sessão do dia 15.04.2024)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "53", "ord": 53, "texto": "Incide contribuição previdenciária sobre o adicional por tempo de serviço recebido pelos servidores públicos do Município de Indaial, haja vista sua natureza remuneratória. (Pedido de Uniformização n. 5006185-1.2022.8.24.0031/SC, Rel. Juiz Jeferson Zanini, sessão do dia 16.09.2024)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "54", "ord": 54, "texto": "Na vigência da LCM n. 46/2011, a majoração do piso salarial profissional nacional do magistério público da educação básica acarreta o aumento automático, e na mesma proporção, dos vencimentos da carreira dos servidores públicos do magistério do quadro de pessoal do Município de Tubarão. (Pedido de Uniformização n. 5007909- 31.2023.8.24.0075/SC, Rel. Juiz Jeferson Zanini, sessão do dia 18.11.2024)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "56", "ord": 56, "texto": "A exigência de ingresso no serviço público até o dia 31.12.2003, que consta no art. 6º da Emenda Constitucional n. 41/2003, refere-se ao cargo de provimento efetivo, não alcançando aqueles de vínculo precário\". (Pedido de Uniformização n. 5018417-25.2022.8.24.0090, Rel. Juiz Marcelo Volpato de Souza, sessão dia 17.02.2025).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "57", "ord": 57, "texto": "É possível o reconhecimento do direito à conversão em pecúnia de saldo de banco de horas acumulado na atividade por policial civil quando da passagem para a inatividade, nos termos do Tema 635 da Repercussão Geral do STF, sob pena de enriquecimento sem causa do Estado, ressalvada a hipótese na qual a Administração Pública comprovadamente facultou o exercício do direito à fruição de folgas e houve recusa por parte do servidor. (Pedido de Uniformização n. 5026675- 87.2023.8.24.0090, Rel. para o Acórdão Juiz Edson Marcos de Mendonça, sessão dia 17.02.2025).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "58", "ord": 58, "texto": "A progressão funcional horizontal por tempo de serviço dos servidores públicos do quadro de pessoal do Município de Alfredo Wagner considera, além do período de trabalho, o desempenho deles no exercício das funções do cargo, razão pela qual pode ser cumulada com o adicional por tempo de serviço sem que ocorra violação à regra positivada no art. 37, XIV, da Constituição Federal (Pedido de Uniformização n. 5002275-92.2022.8.24.0009, Rel. Marcelo Volpato de Souza, sessão 17.02.2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "59", "ord": 59, "texto": "O servidor público aposentado do Município de Mafra conserva o direito de requerer a promoção por aperfeiçoamento por cursos realizados no período anterior à inativação. (Pedido de Uniformização n. 5001736-30.2022.8.24.0041, Rel. Marcelo Volpato de Souza, sessão dia 17.02.2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "60", "ord": 60, "texto": "A concessão do adicional de periculosidade aos servidores públicos estatutários depende de expressa previsão e regulamentação em legislação local, sendo inviável a aplicação subsidiária da Consolidação das Leis do Trabalho (CLT). (Pedido de Uniformização n. 5000342-53.2022.8.24.0084, Rel. Margani de Mello, sessão dia 17.02.2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "61", "ord": 61, "texto": "O ISSQN incide sobre o valor dos materiais empregados na construção civil, salvo se, cumulada e comprovadamente, produzidos pelo prestador fora do local da obra e comercializados com a incidência do ICMS. (Pedido de Uniformização n. 5012788-11.2022.8.24.0045 e n.5017193-56.2023.8.24.0045, Rel. Margani de Mello, sessão dia 17.02.2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "62", "ord": 62, "texto": "A conversão em pecúnia da licença-especial não usufruída pelo servidor militar, com fundamento no artigo 69, §1º, da Lei n. 6.218/1983, e no artigo 9º, da Lei Complementar Estadual n. 52/1992, não depende de prévio requerimento e deferimento de gozo pela Administração Pública. (Pedido de Uniformização n. 5031718-05.2023.8.24.0090, Rel Margani de Mello, sessão dia 17.02.2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "63", "ord": 63, "texto": "1) Não obstante a promulgação da Lei n. 13.281/2016, não é possível reconhecer nulidade em decorrência da inobservância da regra preconizada no art. 261, § 10, do CTB, uma vez que a regulamentação pelo CONTRAN somente foi editada no ano de 2018. Daí porque, até 31/10/2017, não há falar em nulidade em decorrência da inobservância da art. 261, § 10, do CTB, com a redação original dada pela Lei n. Lei n. 13.281/2016; 2) No período compreendido entre a edição Deliberação CONTRAN n. 163, de 31 de outubro de 2017, e a vigência da Lei n. 14.071, de 13 de outubro de 2020 (entrada em vigor 180 dias após a publicação no DOU), em razão da ausência de previsão legal em sentido diverso, deve vigorar o regulamento editado pelo órgão nacional de trânsito competente (art. 7º da Deliberação CONTRAN n. 163/2017), de modo que somente é possível reconhecer nulidade caso tenham sido inobservadas as regras então vigentes e editadas pelo CONTRAN; e 3) após a vigência da Lei n. 14.071, de 13 de outubro de 2020 (entrada em vigor 180 dias após a publicação no DOU), deve ser obrigatoriamente observada a regra prevista no art. 261, § 10, do CTB, com a redação original dada pela Lei n. 14.071/2020, não sendo possível, mesmo diante da Resolução CONTRAN n. 844/2021 (que alterou o Resolução CONTRAN n. 723/2018), afastar a aplicação da regra prevista no CTB quanto à concomitância dos processos de aplicação de penalidade de multa e PSDD, sendo que ambos serão de competência do órgão ou entidade responsável pela aplicação da multa. (Pedido de Uniformização n. 5035019-30.2024.8.24.0023 Rel. Edson Marcos de Mendonça, sessão dia 17.03.2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "64", "ord": 64, "texto": "Os servidores empossados no cargo de Agente de Segurança Socioeducativo do Quadro de Pessoal da Secretaria de Estado da Administração Prisional e Socioeducativa (SAP) sob a vigência da LCE n. 675/2016 não possuem direito a reenquadramento na carreira com a entrada em vigor da LCE n. 777/2021. (Pedido de Uniformização n. 5031602- 21.2023.8.24.0018 e 5039671-20.2023.8.24.0090, Rel. Jaber Farah Filho, sessão dia 14.04.2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "66", "ord": 66, "texto": "A omissão continuada da Administração Pública em proceder à avaliação e progressão funcional do servidor não atinge o fundo do direito, mas tão-somente as parcelas relativas ao quinquênio anterior ao ajuizamento da ação, por se tratar de relação de trato sucessivo. (Pedido de Uniformização de Interpretação de Lei n. 5029508- 04.2021.8.24.0008/SC, Rel. Juíza Margani de Mello, sessão dia 21.10.2024)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "67", "ord": 67, "texto": "É possível a conversão em pecúnia da totalidade da licença especial pelo integrante da carreira Policial Militar do Estado de Santa Catarina, à razão de um período de 30 (trinta) dias por ano, nos termos do art. 9º da Lei Complementar Estadual n. 52/1992. (Pedido de Uniformização n. 5037291-87.2024.8.24.0090, Rel. Edson Marcos de Mendonça, sessão dia 18.08.2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "68", "ord": 68, "texto": "Para fins de recebimento da gratificação e adicional de atividade técnica, a partir da vigência da Lei n. 18.314/2021, o enquadramento dos servidores integrantes do quadro do magistério deve ser realizado de acordo com seu nível de formação (graduação - nível I, especialização - nível II, mestrado - nível III e doutorado - nível IV). (Pedido de Uniformização de Interpretação de Lei n. 5008168-44.2024.8.24.0090/SC, Rel. Juíza Margani de Mello, sessão dia 20.10.2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "69", "ord": 69, "texto": "A instituição de contribuição de melhoria no Município de Curitibanos depende da promulgação prévia de lei ordinária (artigo 82 do CTN), bem como de publicação de edital antes do início das obras (artigo 151 da LCM n. 134/2017), cabendo ao contribuinte o ônus de comprovar o descumprimento das determinações legais. (Pedido de Uniformização de Interpretação de Lei n. 5028457-42.2023.8.24.0022/SC, Rel. Juíza Margani de Mello, sessão dia 20.10.2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "70", "ord": 70, "texto": "O servidor público afastado por força do artigo 76, da Lei Complementar Estadual n. 491/2010, tem direito ao recebimento da integralidade da remuneração, incluindo as horas extraordinárias e o adicional noturno, observado o disposto na Lei n. 774/2021. (Pedido de Uniformização n. 5004393-55.2023.8.24.0090/SC, Rel. Adriana Mendes Bertoncini, sessão dia 21.10.2024)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "71", "ord": 71, "texto": "Quando reconhecida a responsabilidade civil do Município de Navegantes (poder concedente) e da SEMASA de Itajaí (concessionária de serviço público), o que deverá ser examinado pelo órgão julgador competente em cada caso concreto, por se tratar de bem essencial à existência humana, a interrupção indevida do fornecimento e/ou o fornecimento de água imprópria para o consumo, com altos índices de salinidade, no período compreendido entre 13/10/2020 até 06/11/2020, configura danos morais presumidos (in re ipsa), ressalvando-se que a valoração deve ser realizada em atenção às particularidades de cada caso concreto. (Pedido de Uniformização n. 5005223- 80.2023.8.24.0135/SC, Rel. Edson Marcos de Mendonça, sessão dia 14.05.2025).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "72", "ord": 72, "texto": "Aos servidores públicos do município de Balneário Camboriú, não é possível computar o tempo de exercício em contratação temporária, anterior à investidura no cargo efetivo, para fins de adicional por tempo de serviço. (Pedido de Uniformização n. 5013657-31.2021.8.24.0005/SC, Rel. Augusto Cessar Allet Aguiar, sessão dia 23.02.2026)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "73", "ord": 73, "texto": "No âmbito do Juizado Especial da Fazenda Pública, a arguição de erro de cálculo não configura inovação recursal, podendo ser apreciada pelo órgão julgador no recurso cível ou diferida para a fase de cumprimento de sentença. (Pedido de Uniformização n. 5001595-70.2024.8.24.0031/SC, Rel. Jefferson Zanini, sessão dia 23.02.2026)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "74", "ord": 74, "texto": "É válida a notificação de imposição de penalidade realizada por meio de edital, quando restar frustrada a entrega da correspondência enviada ao endereço do proprietário do veículo constante do cadastro do RENAVAM, com a devolução registrada sob a justificativa de \"endereço insuficiente. (Pedido de Uniformização n. 5001627- 70.2023.8.24.0044/SC, Rel. Jefferson Zanini, sessão dia 23.02.2026)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "75", "ord": 75, "texto": "O enquadramento funcional previsto nas linhas de correlação do Anexo IV da LCE n. 675/2016 aplica-se exclusivamente aos servidores investidos, sob a égide da LCE n. 472/2009, nos cargos efetivos de Agente Penitenciário e de Agente de Segurança Socioeducativo que se encontravam em exercício na data de sua entrada em vigor (1º.5.2016), sendo vedado o cômputo de tempo de serviço prestado em outro cargo público, efetivo ou temporário\". (Pedido de Uniformização n. 5026678- 76.2022.8.24.0090/SC, Rel. Jefferson Zanini, sessão dia 23.02.2026)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "76", "ord": 76, "texto": "É possível a conversão em pecúnia da totalidade da licença-prêmio pelo integrante da carreira Policial Civil do Estado de Santa Catarina, à razão de um período de 30 (trinta) dias por ano, nos termos do art. 15, I, da Lei Complementar Estadual n. 55/1992. (Pedido de Uniformização n. 5014564-03.2025.8.24.0090/SC, Rel. Jefferson Zanini, sessão dia 23.02.2026)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "77", "ord": 77, "texto": "Cumulados pedidos de declaração de nulidade e de repetição de indébito tributário, o marco inicial da prescrição quanto à pretensão principal repetitória é o pagamento do tributo, nos termos do art. 168, I, do CTN. (Pedido de Uniformização n. 5002248-86.2023.8.24.0070, Rel. Jaber Farah Filho, sessão dia 21/07/2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "78", "ord": 78, "texto": "Independentemente da natureza pública ou privada da instituição de saúde responsável pelo programa de residência médica, as pretensões referentes ao não fornecimento do auxílio-moradia previsto na lei nº 6.932/81 se submetem ao prazo prescricional quinquenal, contado na forma da súmula 85 do STJ\". (Pedido de Uniformização n. 5021538- 27.2023.8.24.0090, Rel. Augusto Cesar Allet Aguiar, sessão dia 18/08/2025);", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "79", "ord": 79, "texto": "A mora da Administração em conceder promoção funcional a que o servidor fazia jus não pode reverter em seu prejuízo. O reconhecimento do direito, mesmo após a inativação, possui natureza declaratória, impõe a revisão dos proventos, de acordo com a modalidade em que aposentado o servidor, e assegura o pagamento das diferenças apuradas independentemente de acerto de contas previdenciário prévio entre o ente instituidor e o regime próprio, ressalvado o desconto da cota-parte do segurado. (Pedido de Uniformização n. 5004255-71.2023.8.24.0031, Rel. Jaber Farah Filho, sessão dia 18/08/2025)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "80", "ord": 80, "texto": "Para os Agentes Comunitários de Saúde com atividades regidas pela Lei Federal n. 11.350/2006, submetidos a regime estatutário, prevalece a base de cálculo do adicional de insalubridade prevista em lei municipal. (Pedido de Uniformização n. 5007838-05.2024.8.24.0007, Rel. Augusto Cesar Allet Aguiar, sessão dia 16/03/2026 a 24/03/2026)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "81", "ord": 81, "texto": "Os servidores do Município de Canoinhas possuem o direito à progressão por merecimento prevista no artigo 84 da LCM n. 2.305/1990, caso tenham preenchido os requisitos exigidos para tanto antes da revogação operada pela LCM n. 70/2019. (Pedido de Uniformização n 5008471-89.2024.8.24.0015, Rel. Margani de Mello, sessão dia 20/04/2026)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "82", "ord": 82, "texto": "A conversão em pecúnia de até 1/3 (um terço) da licença-prêmio prevista no art. 135, parágrafo único, da Lei n. 6.843/1986, aplicado subsidiariamente aos servidores efetivos da Polícia Científica do Estado de Santa Catarina por força do art. 81 da Lei n. 15.156/2010, não se submete ao juízo de conveniência e oportunidade da Administração Pública. (Pedido de Uniformização n. 5027898-41.2024.8.24.0090, Rel. Fernando Vieira Luiz, sessão dia 18/05/2026 a 25/05/2026)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "83", "ord": 83, "texto": "O servidor público municipal de Itapiranga, em licença para tratamento de saúde, ainda que vinculado ao Regime Geral de Previdência Social, tem direito à preservação da remuneração integral do cargo, cabendo ao Município complementar eventual diferença entre o benefício previdenciário pago pelo INSS e a remuneração que o servidor faria jus se estivesse em atividade, nos termos dos arts. 179 e 180 da Lei Complementar Municipal n. 39/2011. (Pedido de Uniformização n. 03001778120168240034, Rel. Augusto Cesar Allet Aguiar, sessão dia 18/05/2026 a 25/05/2026)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "84", "ord": 84, "texto": "A EC 120/2022, que autoriza a concessão de adicional de insalubridade a agentes comunitários de saúde, não possui eficácia plena, exigindo regulamentação infraconstitucional do ente federativo empregador e de laudo administrativo ou judicial que constate a exposição a agentes insalubres. (Pedido de Uniformização n. 5004974- 19.2023.8.24.0010/SC, Rel. Margani de Mello, sessão dia 15/06/2026).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "85", "ord": 85, "texto": "Até a entrada em vigor da Emenda Constitucional n. 103/2019, admite-se a conjugação da conversão do tempo de serviço especial em comum, prevista no art. 40, § 4º, III, da Constituição Federal, na redação então vigente, com a regra de transição do art. 3º da Emenda Constitucional n. 47/2005, para fins de concessão de aposentadoria voluntária ao servidor público com integralidade e paridade remuneratórias. (Pedido de Uniformização n. 5000069-77.2020.8.24.0041, Rel. Luiz Claudio Broering, sessão dia 20/07/2026 a 27/07/2026)", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "86", "ord": 86, "texto": "A incorporação do adicional de insalubridade aos proventos de aposentadoria, prevista no artigo 18, § 4º, da Lei Complementar Estadual n. 323/2006, é cabível quando o pedido de passagem para a inatividade tenha cumprido seus requisitos até a vigência da Emenda Constitucional n. 103/2019, quais sejam: comprovada a percepção ininterrupta da vantagem nos três anos imediatamente anteriores à EC; e reconhecido o direito à aposentadoria até a data da referida Emenda Constitucional. (Pedido de Uniformização n. 5016027-14.2024.8.24.0090, Rel. Luiz Claudio Broering, sessão dia 17/08/2026).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "87", "ord": 87, "texto": "A incorreta denominação do recurso, por si só, não impede seu conhecimento no sistema dos juizados especiais, desde que, mediante exame concreto e global da insurgência, estejam presentes os requisitos de admissibilidade do recurso efetivamente cabível, especialmente a tempestividade, e não se verifique a adoção de regime recursal incompatível. (Consulta n. 5065215-81.2026.8.24.0000, Rel. para acórdão: Jefferson Zanini, sessão dia 21/09/2026 a 28/09/2026).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "88", "ord": 88, "texto": "Nos juizados especiais, o lançamento de prazo equivocado no sistema eproc não exime as partes da contagem correta, nem configura justa causa para prorrogar o tempo previsto na legislação para recorrer. (Consulta n. 5065230-50.2026.8.24.0000, Rel. Marcelo Pizolati, sessão dia 21/09/2026 a 28/09/2026).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "89", "ord": 89, "texto": "O prazo prescricional quinquenal para cobrança da Taxa de Preservação Ambiental (TPA) no Município de Bombinhas não se inicia com a entrada do veículo do território da municipalidade (fato gerador tributário), e sim, após a constituição definitiva do crédito tributário, cujo prazo decadencial é de cinco anos após a ocorrência do fato gerador, nos termos dos arts. 173, I e 174, ambos do Código Tributário Nacional. (Pedido de Uniformização n. 5024936-22.2024.8.24.0033, Rel. Luiz Claudio Broering, sessão dia 21/09/2026 a 28/09/2026).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – Turma de Uniformização dos Juizados Especiais", "n": "90", "ord": 90, "texto": "A gratificação de regência de classe prevista no art. 50 da Lei Complementar Municipal n. 38/2011, com as alterações promovidas pela Lei Complementar Municipal n. 69/2019 do Município de Canoinhas, é incorporável aos proventos de aposentadoria apenas quando o servidor, antes da entrada em vigor da Emenda Constitucional n. 103/2019, já tenha reunido os requisitos necessários tanto à aposentadoria quanto à incorporação da gratificação. (Pedido de Uniformização n. 5006660-31.2023.8.24.0015, Rel. Cyd Carlos da Silveira, sessão dia 21/09/2026 a 28/09/2026).", "materia": "", "orgao": "Turma de Uniformização dos Juizados Especiais", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "I", "ord": 1, "texto": "Não configura constrangimento ilegal a submissão do condenado ao exame criminológico para análise de pedido de progressão de regime prisional, desde que devidamente fundamentada a necessidade da perícia.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "II", "ord": 2, "texto": "É cabível a remição da pena pelo estudo (Súmula n. 341 do STJ), à proporção de 18 horas-aula por 1 dia da pena remida.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "III", "ord": 3, "texto": "A transferência de sentenciado de outra unidade federativa para o sistema prisional catarinense dependerá de anuência prévia do juízo com competência em execução penal para o qual pretendida a transferência, ouvidos o Ministério Público e a Diretoria de Administração Penal.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "IV", "ord": 4, "texto": "Inexistindo casa do albergado para cumprimento da pena em regime aberto, poderá ser deferido albergue domiciliar.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "V", "ord": 5, "texto": "A decisão sobre cometimento de falta grave é da competência do juiz da execução penal.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "VI", "ord": 6, "texto": "O benefício de saída temporária será deferido ao sentenciado que cumpre pena no regime aberto, desde que satisfaça os requisitos necessários.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "VII", "ord": 7, "texto": "A proibição de trabalho externo em atividade privada alcança somente o preso em regime fechado, ao qual só é admitida a prestação de serviços públicos.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "VIII", "ord": 8, "texto": "A falta grave cometida no regime fechado interrompe o prazo para progressão.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "IX", "ord": 9, "texto": "O prazo prescricional para a aplicação de sanção disciplinar, diante da inexistência de legislação específica, deve ser bienal (art. 109, VI do CP), e contado da data do fato, sendo que em caso de fuga (art. 50, II, da LEP) conta-se da recaptura ou da apresentação espontânea.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "X", "ord": 10, "texto": "O PEC será cadastrado com as peças obrigatórias previstas no art. 316 do Código de Normas da Corregedoria-Geral da Justiça somente quando cumprido o mandado de prisão pelo juízo da condenação e após atualização do histórico da parte no SA J. Inobservadas essas condições indispensáveis para o início da execução penal os documentos serão devolvidos àquele juízo.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "XI", "ord": 11, "texto": "O cálculo do lapso temporal de cumprimento da pena, para a segunda progressão de regime prisional, deverá incidir sobre a pena restante que estava sendo cumprida no novo regime, e não sobre o total da pena cominada.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Fórum Estadual de Magistrados da Execução Penal", "n": "XII", "ord": 12, "texto": "No caso de regressão de regime prisional em decorrência de nova condenação, por crime praticado antes ou durante a execução, o prazo para progressão de regime contar- se-á a partir daquela transferência, provisória ou definitiva, tendo como base o que resta das penas a serem cumpridas.", "materia": "", "orgao": "I Fórum Estadual de Magistrados da Execução Penal", "situacao": "Vigente", "obs": "(*) O I Fórum Estadual de Magistrados da Execução Penal do Estado de Santa Catarina (FEMEPE) foi realizado nos dias 3 e 4 de setembro de 2009. · Disponibilizado no Diário da Justiça Eletrônico n. 785, de 06.10.09, pág. 01.", "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "1", "ord": 1, "texto": "A sentença arbitral não está sujeita à ação rescisória.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "2", "ord": 2, "texto": "Ainda que não haja cláusula compromissória, a Administração Pública poderá celebrar compromisso arbitral.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "3", "ord": 3, "texto": "A carta arbitral poderá ser processada diretamente pelo órgão do Poder Judiciário do foro onde se dará a efetivação da medida ou decisão.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "4", "ord": 4, "texto": "Na arbitragem, cabe à Administração Pública promover a publicidade prevista no art. 2º, § 3º, da Lei n. 9.307/1996, observado o disposto na Lei n. 12.527/2011, podendo ser mitigada nos casos de sigilo previstos em lei, a juízo do árbitro.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "5", "ord": 5, "texto": "A arguição de convenção de arbitragem pode ser promovida por petição simples, a qualquer momento antes do término do prazo da contestação, sem caracterizar preclusão das matérias de defesa, permitido ao magistrado suspender o processo até a resolução da questão.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "6", "ord": 6, "texto": "O processamento da recuperação judicial ou a decretação da falência não autoriza o administrador judicial a recusar a eficácia da convenção de arbitragem, não impede a instauração do procedimento arbitral, nem o suspende.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "7", "ord": 7, "texto": "Os árbitros ou instituições arbitrais não possuem legitimidade para figurar no polo passivo da ação prevista no art. 33, caput, e § 4º, da Lei 9.307/1996, no cumprimento de sentença arbitral e em tutelas de urgência.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "8", "ord": 8, "texto": "São vedadas às instituições de arbitragem e mediação a utilização de expressões, símbolos ou afins típicos ou privativos dos Poderes da República, bem como a emissão de carteiras de identificação para árbitros e mediadores.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "9", "ord": 9, "texto": "A sentença arbitral é hábil para inscrição, arquivamento, anotação, averbação ou registro em órgãos de registros públicos, independentemente de manifestação do Poder Judiciário.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "10", "ord": 10, "texto": "O pedido de declaração de nulidade da sentença arbitral formulado em impugnação ao cumprimento da sentença deve ser apresentado no prazo do art. 33 da Lei 9.307/1996.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "11", "ord": 11, "texto": "Nas arbitragens envolvendo a Administração Pública, é permitida a adoção das regras internacionais de comércio e/ou usos e costumes aplicáveis às respectivas áreas técnicas.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "12", "ord": 12, "texto": "A existência de cláusula compromissória não obsta a execução de título executivo extrajudicial, reservando-se à arbitragem o julgamento das matérias previstas no art. 917, incs. I e VI, do CPC/2015.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "13", "ord": 13, "texto": "Podem ser objeto de arbitragem relacionada à Administração Pública, dentre outros, litígios relativos: I - ao inadimplemento de obrigações contratuais por qualquer das partes; II - à recomposição do equilíbrio econômico-financeiro dos contratos, cláusulas financeiras e econômicas.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "14", "ord": 14, "texto": "A mediação é método de tratamento adequado de controvérsias que deve ser incentivado pelo Estado, com ativa participação da sociedade, como forma de acesso à Justiça e à ordem jurídica justa.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "15", "ord": 15, "texto": "Recomenda-se aos órgãos do sistema de Justiça firmar acordos de cooperação técnica entre si e com Universidades, para incentivo às práticas dos métodos consensuais de solução de conflitos, bem assim com empresas geradoras de grande volume de demandas, para incentivo à prevenção e à solução extrajudicial de litígios.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "16", "ord": 16, "texto": "O magistrado pode, a qualquer momento do processo judicial, convidar as partes para tentativa de composição da lide pela mediação extrajudicial, quando entender que o conflito será adequadamente solucionado por essa forma.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "17", "ord": 17, "texto": "Nos processos administrativo e judicial, é dever do Estado e dos operadores do Direito propagar e estimular a mediação como solução pacífica dos conflitos.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "18", "ord": 18, "texto": "Os conflitos entre a administração pública federal direta e indireta e/ou entes da federação poderão ser solucionados pela Câmara de Conciliação e Arbitragem da Administração Pública Federal - CCAF - órgão integrante da Advocacia-Geral da União, via provocação do interessado ou comunicação do Poder Judiciário.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "19", "ord": 19, "texto": "O acordo realizado perante a Câmara de Conciliação e Arbitragem da Administração Pública Federal - CCAF - órgão integrante da Advocacia-Geral da União - constitui título executivo extrajudicial e, caso homologado judicialmente, título executivo judicial.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "20", "ord": 20, "texto": "Enquanto não for instalado o Centro Judiciário de Solução de Conflitos e Cidadania (Cejusc), as sessões de mediação e conciliação processuais e pré-processuais poderão ser realizadas por meio audiovisual, em módulo itinerante do Poder Judiciário ou em entidades credenciadas pelo Núcleo Permanente de Métodos Consensuais de Solução de Conflitos (Nupemec), no foro em que tramitar o processo ou no foro competente para o conhecimento da causa, no caso de mediação e conciliação pré-processuais.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "21", "ord": 21, "texto": "É facultado ao magistrado, em colaboração com as partes, suspender o processo judicial enquanto é realizada a mediação, conforme o art. 313, II, do Código de Processo Civil, salvo se houver previsão contratual de cláusula de mediação com termo ou condição, situação em que o processo deverá permanecer suspenso pelo prazo previamente acordado ou até o implemento da condição, nos termos do art. 23 da Lei n.13.140/2015.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "22", "ord": 22, "texto": "A expressão \"sucesso ou insucesso\" do art.167, § 3º, do Código de Processo Civil não deve ser interpretada como quantidade de acordos realizados, mas a partir de uma avaliação qualitativa da satisfação das partes com o resultado e com o procedimento, fomentando a escolha da câmara, do conciliador ou do mediador com base nas suas qualificações e não nos resultados meramente quantitativos.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "23", "ord": 23, "texto": "Recomenda-se que as faculdades de direito mantenham estágios supervisionados nos escritórios de prática jurídica para formação em mediação e conciliação e promovam parcerias com entidades formadoras de conciliadores e mediadores, inclusive tribunais, Ministério Público, OAB, defensoria e advocacia pública.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "24", "ord": 24, "texto": "Sugere-se que as faculdades de direito instituam disciplinas autônomas e obrigatórias e projetos de extensão destinados à mediação, à conciliação e à arbitragem, nos termos dos arts. 2º, § 1º, VIII, e 8º, ambos da Resolução CNE/CES n. 9, de 29 de setembro de 2004.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "25", "ord": 25, "texto": "A União, os Estados, o Distrito Federal e os Municípios têm o dever de criar Câmaras de Prevenção e Resolução Administrativa de Conflitos com atribuição específica para autocomposição do litígio.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "26", "ord": 26, "texto": "É admissível, no procedimento de mediação, em casos de fundamentada necessidade, a participação de crianças, adolescentes e jovens - respeitado seu estágio de desenvolvimento e grau de compreensão - quando o conflito (ou parte dele) estiver relacionado aos seus interesses ou direitos.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "27", "ord": 27, "texto": "Recomenda-se o desenvolvimento de programas de fomento de habilidades para o diálogo e para a gestão de conflitos nas escolas, como elemento formativo-educativo, objetivando estimular a formação de pessoas com maior competência para o diálogo, a negociação de diferenças e a gestão de controvérsias.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "28", "ord": 28, "texto": "Propõe-se a implementação da cultura de resolução de conflitos por meio da mediação, como política pública, nos diversos segmentos do sistema educacional, visando auxiliar na resolução extrajudicial de conflitos de qualquer natureza, utilizando mediadores externos ou capacitando alunos e professores para atuarem como facilitadores de diálogo na resolução e prevenção dos conflitos surgidos nesses ambientes.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "29", "ord": 29, "texto": "Caso qualquer das partes comprove a realização de mediação ou conciliação antecedente à propositura da demanda, o magistrado poderá dispensar a audiência inicial de mediação ou conciliação, desde que tenha tratado da questão objeto da ação e tenha sido conduzida por mediador ou conciliador capacitado.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "30", "ord": 30, "texto": "Nas mediações realizadas gratuitamente em programas, câmaras e núcleos de prática jurídica de faculdades de direito, os professores, orientadores e coordenadores que não estejam atuando ou participando no caso concreto, não estão impedidos de assessorar ou representar as partes, em suas especialidades.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "31", "ord": 31, "texto": "É recomendável a existência de uma advocacia pública colaborativa entre os entes da federação e seus respectivos órgãos públicos, nos casos em que haja interesses públicos conflitantes/divergentes. Nessas hipóteses, União, Estados, Distrito Federal e Municípios poderão celebrar pacto de não propositura de demanda judicial e de solicitação de suspensão das que estiverem propostas com estes, integrando o polo passivo da demanda, para que sejam submetidos à oportunidade de diálogo produtivo e consenso sem interferência jurisdicional.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "32", "ord": 32, "texto": "A ausência da regulamentação prevista no art. 1º da Lei n. 9.469/1997 não obsta a autocomposição por parte de integrante da Advocacia-Geral da União e dirigentes máximos das empresas públicas federais nem, por si só, torna-a inadmissível para efeito do inc. II do § 4º do art. 334 do CPC/2015.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "33", "ord": 33, "texto": "É recomendável a criação de câmara de mediação a fim de possibilitar a abertura do diálogo, incentivando e promovendo, nos termos da lei, a regularização das atividades sujeitas ao licenciamento ambiental que estão funcionando de forma irregular, ou seja, incentivar e promover o chamado \"licenciamento de reg ularização\" ou \"licenciamento corretivo\".", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "34", "ord": 34, "texto": "Se constatar a configuração de uma notória situação de desequilíbrio entre as partes, o mediador deve alertar sobre a importância de que ambas obtenham, organizem e analisem dados, estimulando-as a planejarem uma eficiente atuação na negociação.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "35", "ord": 35, "texto": "Os pedidos de homologação de acordos extrajudiciais deverão ser feitos no Centro Judiciário de Solução de Conflitos e Cidadania, onde houver.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "36", "ord": 36, "texto": "Para estimular soluções administrativas em ações previdenciárias, quando existir matéria de fato a ser comprovada, as partes poderão firmar acordo para a reabertura do processo administrativo com o objetivo de realizar, por servidor do INSS em conjunto com a Procuradoria, procedimento de justificação administrativa, pesquisa externa e/ou vistoria técnica, com possibilidade de revisão da decisão original.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "37", "ord": 37, "texto": "Recomenda-se a criação de câmaras previdenciárias de mediação ou implantação de procedimentos de mediação para solucionar conflitos advindos de indeferimentos, suspensões e cancelamentos de benefícios previdenciários, ampliando o acesso à justiça e permitindo à administração melhor gerenciamento de seu processo de trabalho.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "38", "ord": 38, "texto": "O Estado promoverá a cultura da mediação no sistema prisional, entre internos, como forma de possibilitar a ressocialização, a paz social e a dignidade da pessoa humana.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "39", "ord": 39, "texto": "A previsão de suspensão do processo para que as partes se submetam à mediação extrajudicial deverá atender ao disposto no § 2º do art. 334 da Lei Processual, podendo o prazo ser prorrogado no caso de consenso das partes.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "40", "ord": 40, "texto": "Nas mediações de conflitos coletivos envolvendo políticas públicas, judicializados ou não, deverá ser permitida a participação de todos os potencialmente interessados, dentre eles: (i) entes públicos (Poder Executivo ou Legislativo) com competências relativas à matéria envolvida no conflito; (ii) entes privados e grupos sociais diretamente afetados; (iii) Ministério Público; (iv) Defensoria Pública, quando houver interesse de vulneráveis; e (v) entidades do terceiro setor representativas que atuem na matéria afeta ao conflito.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "41", "ord": 41, "texto": "Além dos princípios já elencados no art. 2º da Lei 13.140/2015, a mediação também deverá ser orientada pelo Princípio da Decisão Informada.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "42", "ord": 42, "texto": "O membro do Ministério Público designado para exercer as funções junto aos centros, câmaras públicas de mediação e qualquer outro espaço em que se faça uso das técnicas de autocomposição, para o tratamento adequado de conflitos, deverá ser capacitado em técnicas de mediação e negociação, bem como de construção de consenso.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "43", "ord": 43, "texto": "O membro do Ministério Público com atribuição para o procedimento consensual, devidamente capacitado nos métodos negociais e autocompositivos, quando atuar como mediador, ficará impedido de exercer atribuições típicas de seu órgão de execução, cabendo tal intervenção, naquele feito, a seu substituto legal.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "44", "ord": 44, "texto": "Havendo processo judicial em curso, a escolha de mediador ou câmara privada ou pública de conciliação e mediação deve observar o peticionamento individual ou conjunto das partes, em qualquer tempo ou grau de jurisdição, respeitado o contraditório.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "45", "ord": 45, "texto": "A mediação e conciliação são compatíveis com a recuperação judicial, a extrajudicial e a falência do empresário e da sociedade empresária, bem como em casos de superendividamento, observadas as restrições legais.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "46", "ord": 46, "texto": "Os mediadores e conciliadores devem respeitar os padrões éticos de confidencialidade na mediação e conciliação, não levando aos magistrados dos seus respectivos feitos o conteúdo das sessões, com exceção dos termos de acordo, adesão, desistência e solicitação de encaminhamentos, para fins de ofícios.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "47", "ord": 47, "texto": "A menção à capacitação do mediador extrajudicial, prevista no art. 9º da Lei n.13.140/2015, indica que ele deve ter experiência, vocação, confiança dos envolvidos e aptidão para mediar, bem como conhecimento dos fundamentos da mediação, não bastando formação em outras áreas do saber que guardem relação com o mérito do conflito.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "48", "ord": 48, "texto": "É recomendável que, na judicialização da saúde, previamente à propositura de ação versando sobre a concretização do direito à saúde - fornecimento de medicamentos e/ou internações hospitalares -, promova-se uma etapa de composição extrajudicial mediante interlocução com os órgãos estatais de saúde.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "49", "ord": 49, "texto": "Os Comitês de Resolução de Disputas (Dispute Boards) são método de solução consensual de conflito, na forma prevista no § 3° do art. 3º do Código de Processo Civil Brasileiro.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "50", "ord": 50, "texto": "O Poder Público, os fornecedores e a sociedade deverão estimular a utilização de mecanismos como a plataforma CONSUMIDOR.GOV.BR, política pública criada pela Secretaria Nacional do Consumidor - Senacon e pelos Procons, com vistas a possibilitar o acesso, bem como a solução dos conflitos de consumo de forma extrajudicial, de maneira rápida e eficiente.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "51", "ord": 51, "texto": "O Estado e a sociedade deverão estimular as soluções consensuais nos casos de superendividamento ou insolvência do consumidor pessoa física, a fim de assegurar a sua inclusão social, o mínimo existencial e a dignidade da pessoa humana.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "52", "ord": 52, "texto": "O Poder Público e a sociedade civil incentivarão a facilitação de diálogo dentro do âmbito escolar, por meio de políticas públicas ou parcerias público-privadas que fomentem o diálogo sobre questões recorrentes, tais como: bullying, agressividade, mensalidade escolar e até atos infracionais. Tal incentivo pode ser feito por oferecimento da prática de círculos restaurativos ou outra prática restaurativa similar, como prevenção e solução dos conflitos escolares.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "53", "ord": 53, "texto": "Estimula-se a transação como alternativa válida do ponto de vista jurídico para tornar efetiva a justiça tributária, no âmbito administrativo e judicial, aprimorando a sistemática de prevenção e solução consensual dos conflitos tributários entre Administração Pública e administrados, ampliando, assim, a recuperação de receitas com maior brevidade e eficiência.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "54", "ord": 54, "texto": "A Administração Pública deverá oportunizar a transação por adesão nas hipóteses em que houver precedente judicial de observância obrigatória.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "55", "ord": 55, "texto": "O Poder Judiciário e a sociedade civil deverão fomentar a adoção da advocacia colaborativa como prática pública de resolução de conflitos na área do direito de família, de modo a que os advogados das partes busquem sempre a atuação conjunta voltada para encontrar um ajuste viável, criativo e que beneficie a todos os envolvidos.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "56", "ord": 56, "texto": "As ouvidorias servem como um importante instrumento de solução extrajudicial de conflitos, devendo ser estimulada a sua implantação, tanto no âmbito das empresas, como da Administração Pública.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "57", "ord": 57, "texto": "As comunidades têm autonomia para escolher o modelo próprio de mediação comunitária, não devendo se submeter a padronizações ou modelos únicos.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "58", "ord": 58, "texto": "A conciliação/mediação, em meio eletrônico, poderá ser utilizada no procedimento comum e em outros ritos, em qualquer tempo e grau de jurisdição.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "59", "ord": 59, "texto": "A obrigação de estimular a adoção da conciliação, da mediação e de outros métodos consensuais de solução de conflitos prevista no § 3º do art. 3º do Código de Processo Civil aplica-se às entidades que promovem a autorregulação, inclusive no âmbito dos processos administrativos que tenham curso nas referidas entidades.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "60", "ord": 60, "texto": "As vias adequadas de solução de conflitos previstas em lei, como a conciliação, a arbitragem e a mediação, são plenamente aplicáveis à Administração Pública e não se incompatibilizam com a indisponibilidade do interesse público, diante do Novo Código de Processo Civil e das autorizações legislativas pertinentes aos entes públicos.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "61", "ord": 61, "texto": "Os gestores, defensores e advogados públicos que, nesta qualidade, venham a celebrar transações judiciais ou extrajudiciais, no âmbito de procedimento de conciliação, mediação ou arbitragem, não responderão civil, administrativa ou criminalmente, exceto se agirem mediante dolo ou fraude.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "62", "ord": 62, "texto": "Os representantes judiciais da União, autarquias, fundações e empresas públicas federais têm autorização legal, decorrente da Lei n. 10.259, de 12 de julho de 2001 para, diretamente, conciliar, transigir ou desistir de recursos em quaisquer processos, judiciais ou extrajudiciais, cujo valor da causa esteja dentro da alçada equivalente à dos juizados especiais federais.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "63", "ord": 63, "texto": "A perspectiva da conciliação judicial, inclusive por adesão, em razão ou no bojo de Incidente de Resolução de Demandas Repetitivas, é compatível com o Código de Processo Civil (Lei n. 13.105, de 16 de março de 2015) e com a Lei da Mediação (Lei n. 13.140, de 26 de junho de 2015).", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "64", "ord": 64, "texto": "Os dirigentes máximos de entes estatais que exploram atividade econômica podem delegar à sua área jurídica a capacidade de intervir na resolução de litígios extrajudiciais provocados por clientes, em virtude de falhas ocorridas na realização de negócios, emitindo manifestação de caráter mandatório às demais áreas da instituição com a finalidade de indenizar (patrimonial e/ou extrapatrimonialmente) ou solicitar providências que reparem o dano causado aos clientes, de acordo com a legislação e jurisprudência pertinentes.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "65", "ord": 65, "texto": "O emprego dos meios consensuais de solução de conflito deve ser estimulado nacionalmente como política pública, podendo ser utilizados nos Centros de Referência da Assistência Social (CRAS), cujos profissionais, predominantemente psicólogos e assistentes sociais, lotados em áreas de vulnerabilidade social, estão voltados à atenção básica e preventiva.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "66", "ord": 66, "texto": "É fundamental a atualização das matrizes curriculares dos cursos de direito, bem como a criação de programas de formação continuada aos docentes do ensino superior jurídico, com ênfase na temática da prevenção e solução extrajudicial de litígios e na busca pelo consenso.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "67", "ord": 67, "texto": "Nos colégios recursais, o relator poderá, monocraticamente, encaminhar os litígios aos Centros Judiciários de Solução de Conflitos e Cidadania.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "68", "ord": 68, "texto": "O atendimento interdisciplinar realizado por psicólogos e assistentes sociais, no âmbito da Defensoria Pública e do Ministério Público, promove a solução extrajudicial dos litígios, constituindo-se forma de composição e administração de conflitos complementar à mediação, conciliação e arbitragem.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "69", "ord": 69, "texto": "A Administração Pública, sobretudo na área tributária e previdenciária, deve adotar, ex officio, a interpretação pacificada de normas legais e constitucionais, respectivamente, no Superior Tribunal de Justiça e no Supremo Tribunal Federal, independentemente de julgamento em caso de recursos repetitivos ou repercussão geral ou de edição de súmula vinculante.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "70", "ord": 70, "texto": "Quando questionada a juridicidade das decisões tomadas por meio de novas tecnologias de resolução de controvérsias, deve -se atuar com parcimônia e postura receptiva, buscando valorizar e aceitar os acordos oriundos dos meios digitais.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "71", "ord": 71, "texto": "Tendo havido prévio e comprovado requerimento administrativo, incumbe à Administração Pública o dever de comprovar em juízo que adotou as providências legais e regulamentares para a aferição do direito da parte.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "72", "ord": 72, "texto": "As instituições privadas que lidarem com mediação, conciliação e arbitragem, bem como com demais métodos adequados de solução de conflitos, não deverão conter, tanto no título de estabelecimento, marca ou nome, dentre outros, nomenclaturas e figuras que se assimilem à ideia de Poder Judiciário.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "73", "ord": 73, "texto": "A educação para a cidadania constitui forma adequada de solução e prevenção de conflitos, na via extrajudicial, e deve ser adotada e incentivada como política pública privilegiada de tratamento adequado do conflito pelo sistema de justiça.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "74", "ord": 74, "texto": "Havendo autorização legal para a utilização de métodos adequados de solução de controvérsias envolvendo órgãos, entidades ou pessoas jurídicas da Administração Pública, o agente público deverá: (i) analisar a admissibilidade de eventual pedido de resolução consensual do conflito; e (ii) justificar por escrito, com base em critérios objetivos, a decisão de rejeitar a proposta de acordo.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "75", "ord": 75, "texto": "As empresas e organizações devem ser incentivadas a implementar, em suas estruturas organizacionais, um plano estratégico consolidado para prevenção, gerenciamento e resolução de disputas, com o uso de métodos adequados de solução de controvérsias. Tal plano deverá prever métricas de sucesso e diagnóstico periódico, com vistas ao constante aprimoramento. O Poder Judiciário, as faculdades de direito e as instituições observadoras ou reguladoras das atividades empresariais devem promover, medir e premiar anualmente tais iniciativas.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "76", "ord": 76, "texto": "As decisões proferidas por um Comitê de Resolução de Disputas (Dispute Board), quando os contratantes tiverem acordado pela sua adoção obrigatória, vinculam as partes ao seu cumprimento até que o Poder Judiciário ou o juízo arbitral competente emitam nova decisão ou a confirmem, caso venham a ser provocados pela parte inconformada.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "77", "ord": 77, "texto": "Havendo registro ou expressa autorização do juízo sucessório competente, nos autos do procedimento de abertura e cumprimento de testamento, sendo todos os interessados capazes e concordes, o inventário e partilha poderão ser feitos por escritura pública, mediante acordo dos interessados, como forma de pôr fim ao procedimento judicial.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "78", "ord": 78, "texto": "Recomenda-se aos juízes das varas de família dos tribunais onde já tenham sido implantadas as oficinas de parentalidade que as partes sejam convidadas a participar das referidas oficinas, antes da citação nos processos de guarda, visitação e alienação parental, como forma de fomentar o diálogo e prevenir litígios.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "79", "ord": 79, "texto": "O Judiciário estimulará o planejamento sucessório, com ações na área de comunicação que esclareçam os benefícios da autonomia privada, com o fim de prevenir litígios e desestimular a via judiciária.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "80", "ord": 80, "texto": "A utilização dos Comitês de Resolução de Disputas (Dispute Boards), com a inserção da respectiva cláusula contratual, é recomendável para os contratos de construção ou de obras de infraestrutura, como mecanismo voltado para a prevenção de litígios e redução dos custos correlatos, permitindo a imediata resolução de conflitos surgidos no curso da execução dos contratos.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "81", "ord": 81, "texto": "A conciliação, a arbitragem e a mediação, previstas em lei, não excluem outras formas de resolução de conflitos que decorram da autonomia privada, desde que o objeto seja lícito e as partes sejam capazes.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "82", "ord": 82, "texto": "O Poder Público, o Poder Judiciário, as agências reguladoras e a sociedade civil deverão estimular, mediante a adoção de medidas concretas, o uso de plataformas tecnológicas para a solução de conflitos de massa.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "83", "ord": 83, "texto": "O terceiro imparcial, escolhido pelas partes para funcionar na resolução extrajudicial de conflitos, não precisa estar inscrito na Ordem dos Advogados do Brasil e nem integrar qualquer tipo de conselho, entidade de classe ou associação, ou nele inscrever-se.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "84", "ord": 84, "texto": "O Poder Público - inclusive o Poder Judiciário - e a sociedade civil deverão estimular a criação, no âmbito das procuradorias municipais e estaduais, de centros de solução de conflitos, voltados à solução de litígios entre a Administração Pública e os cidadãos, como, por exemplo, a Central de Negociação da Procuradoria-Geral da União.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "85", "ord": 85, "texto": "O Poder Público - inclusive o Poder Judiciário - e a sociedade civil deverão estimular a criação, no âmbito das entidades de classe, de conselhos de autorregulamentação, voltados para a solução de conflitos setoriais.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "86", "ord": 86, "texto": "O Poder Público promoverá a capacitação massiva em técnicas de gestão de conflitos comunitários para policiais militares e guardas municipais.", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}, {"fonte": "TJSC – I Jornada Prevenção e Solução Extrajudicial de Litígios", "n": "87", "ord": 87, "texto": "O Poder Público e a sociedade civil estimularão a expansão e fortalecimento de ouvidorias dos órgãos do sistema de justiça, optando por um modelo inovador e ativo, com a figura essencial de ouvidor/ouvidora independente das corporações a que estão vinculados (as).", "materia": "", "orgao": "I Jornada Prevenção e Solução Extrajudicial de Litígios", "situacao": "Vigente", "obs": null, "mods": ["oab", "magsc", "mpsc", "magfed", "enam"]}]));
